export function iso9001FoundationSourceTr(code: string) {
  const direct = ISO9001_FOUNDATION_SOURCE_TR[code];
  if (direct) return direct;
  return Object.entries(ISO9001_FOUNDATION_SOURCE_TR)
    .filter(([sourceCode]) => sourceCode.startsWith(`${code}.`))
    .map(([sourceCode, text]) => `${sourceCode}\n${text}`)
    .join("\n\n");
}

export function iso9001FoundationFigureDetailsTr(code: string) {
  const direct = ISO9001_FIGURE_DETAILS_TR[code];
  if (direct) return direct;
  return Object.entries(ISO9001_FIGURE_DETAILS_TR)
    .filter(([sourceCode]) => sourceCode.startsWith(`${code}.`))
    .flatMap(([, details]) => details);
}
